func unionFrame(for windowIDs: ArraySlice<WindowID>, in frames: [WindowID: CGRect]) -> CGRect? {
    let knownFrames = windowIDs.compactMap { frames[$0] }
    guard var result = knownFrames.first else { return nil }
    for frame in knownFrames.dropFirst() {
        result = result.union(frame)
    }
    return result
}

public static func plan(_ request: LayoutRequest) -> LayoutPlan {
    switch request.mode {
    case .bsp:
        return BSPLayoutStrategy().plan(request)
    case .masterStack:
        return MasterStackLayoutStrategy(masterRatio: CGFloat(request.masterRatio)).plan(request)
    case .float:
        return FloatLayoutStrategy().plan(request)
    case .spatialBsp, .mutableBsp:
        // `mutableBsp` n'est plus qu'un alias décodable de l'arbre (SPEC-017 A8, FR-018).
        return SpatialBSPLayoutStrategy().plan(request)

